-- Run only in an enclosing BEGIN/ROLLBACK rehearsal after both new migrations.
-- Existing users/catalog are read-only fixture anchors. All financial rows roll back.
CREATE FUNCTION pg_temp.finance_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Finance test failed: %',label; END IF; END $$;
CREATE TEMP TABLE finance_test_evidence(check_name text PRIMARY KEY);
DO $$
DECLARE c uuid; owner_id uuid; other_id uuid; product_id uuid; price numeric; cash uuid; bank uuid; wh uuid; wh2 uuid; item uuid; customer uuid; supplier uuid; shift_id uuid; sale_id uuid; invoice_id uuid; result jsonb; snap jsonb; req uuid:=gen_random_uuid(); payload jsonb; before_qty numeric; expected numeric; caught boolean;
BEGIN
 SELECT b.id,b.owner_user_id,p.id,p.price INTO c,owner_id,product_id,price FROM public.cafes b JOIN public.profiles o ON o.id=b.owner_user_id AND o.status='active' JOIN public.menu_products p ON p.cafe_id=b.id AND p.available AND p.deleted_at IS NULL AND p.price>0 WHERE b.deleted_at IS NULL AND b.status IN('active','published') ORDER BY b.created_at,p.sort_order LIMIT 1;
 IF c IS NULL THEN RAISE EXCEPTION 'Need an active owner and one existing priced product fixture'; END IF;
 SELECT id INTO other_id FROM public.profiles WHERE id<>owner_id AND status='active' LIMIT 1;
 UPDATE public.platform_plans SET active=true,price_sar=1099 WHERE id='finance';
 INSERT INTO public.subscriptions(cafe_id,plan_id,status,started_at,expires_at) VALUES(c,'finance','active',now()-interval '1 day',now()+interval '1 day');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 snap:=public.brand_finance_snapshot(c);
 PERFORM pg_temp.finance_assert((snap->>'canAdminister')::boolean,'owner authorized');
 SELECT id INTO cash FROM public.bf_accounts WHERE cafe_id=c AND code='1000'; SELECT id INTO bank FROM public.bf_accounts WHERE cafe_id=c AND code='1010'; SELECT id INTO wh FROM public.bf_warehouses WHERE cafe_id=c LIMIT 1;
 PERFORM public.brand_finance_execute(c,'settings','{"vatRate":15,"taxInclusive":true,"closedThrough":""}',gen_random_uuid());
 customer:=(public.brand_finance_execute(c,'party','{"name":"Finance rehearsal customer","kind":"customer"}',gen_random_uuid())->>'id')::uuid;
 supplier:=(public.brand_finance_execute(c,'party','{"name":"Finance rehearsal supplier","kind":"supplier"}',gen_random_uuid())->>'id')::uuid;
 item:=(public.brand_finance_execute(c,'item',jsonb_build_object('name','Finance rehearsal item','sku','REHEARSAL-'||gen_random_uuid(),'unit','unit','menuProductId',product_id),gen_random_uuid())->>'id')::uuid;
 PERFORM public.brand_finance_execute(c,'treasury',jsonb_build_object('kind','opening','accountId',cash,'amount',10000),gen_random_uuid());
 shift_id:=(public.brand_finance_execute(c,'shift_open',jsonb_build_object('accountId',cash,'openingCash',10000),gen_random_uuid())->>'id')::uuid;
 invoice_id:=(public.brand_finance_execute(c,'purchase',jsonb_build_object('partyId',supplier,'warehouseId',wh,'lines',jsonb_build_array(jsonb_build_object('itemId',item,'quantity',10,'unitPrice',11.5)),'paid',0),gen_random_uuid())->>'id')::uuid;
 PERFORM pg_temp.finance_assert((SELECT quantity=10 AND average_cost=10 FROM public.bf_stock WHERE item_id=item AND warehouse_id=wh),'VAT inclusive weighted cost');
 payload:=jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('productId',product_id,'quantity',2,'expectedUnitPrice',price,'unitPrice',0.01)),'warehouseId',wh,'shiftId',shift_id,'accountId',cash,'discount',0,'expectedTotal',price*2);
 result:=public.brand_finance_execute(c,'sale',payload,req); sale_id:=(result->>'id')::uuid;
 PERFORM pg_temp.finance_assert((SELECT total=price*2 FROM public.bf_documents WHERE id=sale_id),'database price authority');
 PERFORM pg_temp.finance_assert((public.brand_finance_execute(c,'sale',payload,req)->>'duplicate')::boolean,'exact retry');
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'sale',payload||'{"discount":1}',req); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'idempotency payload conflict');
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'sale',jsonb_set(payload,'{lines,0,quantity}','999'),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'oversell/stale total rejected');
 PERFORM pg_temp.finance_assert((SELECT quantity=8 FROM public.bf_stock WHERE item_id=item AND warehouse_id=wh),'failed transaction stock rollback');
 PERFORM public.brand_finance_execute(c,'refund',jsonb_build_object('documentId',sale_id),gen_random_uuid());
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'refund',jsonb_build_object('documentId',sale_id),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'refund once');
 PERFORM public.brand_finance_execute(c,'settlement',jsonb_build_object('documentId',invoice_id,'accountId',cash,'amount',60),gen_random_uuid());
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'settlement',jsonb_build_object('documentId',invoice_id,'accountId',cash,'amount',60),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'cumulative settlement limit');
 PERFORM public.brand_finance_execute(c,'settlement',jsonb_build_object('documentId',invoice_id,'accountId',cash,'amount',55),gen_random_uuid());
 PERFORM public.brand_finance_execute(c,'refund',jsonb_build_object('documentId',invoice_id),gen_random_uuid());
 PERFORM pg_temp.finance_assert((SELECT quantity=0 FROM public.bf_stock WHERE item_id=item AND warehouse_id=wh),'settled purchase refund restores stock');
 PERFORM pg_temp.finance_assert((SELECT coalesce(sum(j.debit-j.credit),0)=10000 FROM public.bf_journal j WHERE account_id=cash),'settled purchase refund restores money');
 wh2:=(public.brand_finance_execute(c,'warehouse','{"name":"Finance rehearsal warehouse"}',gen_random_uuid())->>'id')::uuid;
 PERFORM public.brand_finance_execute(c,'stock_adjust',jsonb_build_object('itemId',item,'warehouseId',wh,'quantity',5,'unitCost',8),gen_random_uuid());
 PERFORM public.brand_finance_execute(c,'stock_transfer',jsonb_build_object('itemId',item,'warehouseId',wh,'toWarehouseId',wh2,'quantity',2),gen_random_uuid());
 PERFORM pg_temp.finance_assert((SELECT sum(quantity)=5 FROM public.bf_stock WHERE item_id=item),'warehouse transfer preserves quantity');
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'stock_adjust',jsonb_build_object('itemId',item,'warehouseId',wh,'quantity',-100,'unitCost',0),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'negative stock denied');
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'treasury',jsonb_build_object('kind','expense','accountId',cash,'amount','NaN'),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'nonfinite amount denied');
 caught:=false; BEGIN PERFORM public.brand_finance_execute(c,'journal',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('accountId',cash,'debit',10,'credit',0),jsonb_build_object('accountId',bank,'debit',0,'credit',9))),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'unbalanced journal denied');
 PERFORM public.brand_finance_execute(c,'shift_close',jsonb_build_object('shiftId',shift_id,'countedCash',9999),gen_random_uuid());
 PERFORM pg_temp.finance_assert((SELECT status='closed' AND variance=-1 FROM public.bf_shifts WHERE id=shift_id),'counted variance posts on close');
 PERFORM pg_temp.finance_assert((SELECT sum(debit-credit)=0 FROM public.bf_journal WHERE cafe_id=c),'ledger balances');
 caught:=false; BEGIN UPDATE public.bf_documents SET note='tamper' WHERE id=sale_id; EXCEPTION WHEN OTHERS THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'posted invoice immutable');
 PERFORM pg_temp.finance_assert(NOT has_function_privilege('anon','public.brand_finance_execute(uuid,text,jsonb,uuid)','EXECUTE'),'anonymous execute revoked');
 PERFORM pg_temp.finance_assert(NOT has_table_privilege('authenticated','public.bf_documents','SELECT') AND NOT has_table_privilege('authenticated','public.bf_journal','INSERT'),'direct reads and writes revoked');
 PERFORM set_config('request.jwt.claim.sub','',true); caught:=false; BEGIN PERFORM public.brand_finance_snapshot(c); EXCEPTION WHEN insufficient_privilege THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'anonymous session denied');
 IF other_id IS NOT NULL THEN PERFORM set_config('request.jwt.claim.sub',other_id::text,true); caught:=false; BEGIN PERFORM public.brand_finance_snapshot(c); EXCEPTION WHEN insufficient_privilege THEN caught:=true; END; PERFORM pg_temp.finance_assert(caught,'foreign user denied'); END IF;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 snap:=public.brand_finance_snapshot(c); PERFORM pg_temp.finance_assert((snap#>>'{summary,profit}')::numeric=(snap#>>'{summary,sales}')::numeric-(snap#>>'{summary,expenses}')::numeric,'authoritative report totals');
 PERFORM pg_temp.finance_assert(jsonb_array_length(public.brand_finance_history(c,'documents',0)->'rows')>0,'paginated history');
 INSERT INTO finance_test_evidence VALUES('25 actual PostgreSQL authorization, stock, VAT, price authority, idempotency, settled refunds, cumulative settlement, immutable journals and cash count checks');
END $$;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT * FROM finance_test_evidence;
